import{_ as p,r as a,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"File Uploads - October CMS - 4.x","titleTemplate":false,"description":"Easily handle uploading files.","frontmatter":{"subtitle":"Easily handle uploading files."},"headers":[{"level":2,"title":"Uploading Files","slug":"uploading-files","link":"#uploading-files","children":[{"level":3,"title":"Uploading Multiple Files","slug":"uploading-multiple-files","link":"#uploading-multiple-files","children":[]},{"level":3,"title":"Validating File Uploads","slug":"validating-file-uploads","link":"#validating-file-uploads","children":[]}]},{"level":2,"title":"Uploading to Models","slug":"uploading-to-models","link":"#uploading-to-models","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/features/uploads.md","filePath":"4.x/cms/features/uploads.md"}'),u={name:"4.x/cms/features/uploads.md"};function r(k,s,d,g,h,f){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[n(t),s[0]||(s[0]=c("h1",null,"File Uploads",-1)),n(e),s[1]||(s[1]=i(`<p>October CMS provides simple features for uploading files through form submissions. The feature is opt-in to the AJAX framework for the best performance.</p><h2 id="uploading-files"><a href="#uploading-files" class="header-anchor">#</a> Uploading Files</h2><p>To enable file uploads on a form, include the <code>data-request-files</code> attribute on a HTML form tag. The following is a minimal example uploading a file.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onUploadFiles<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-files</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Single File<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>single_file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Upload
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block aside"><p>View the <a href="./../../extend/services/request-input.html">request and input article</a> to learn more about the available methods on the <code>files()</code> function.</p></div><p>Inside your <a href="./../../ajax/handlers.html">AJAX handler</a>, use the <code>files()</code> helper function to access the uploaded file, and call the <code>store</code> method to save the file to <a href="./../../extend/services/storage.html">a storage disk</a>. The resulting value is the local file path to the saved file.</p><p>The following stores the upload in the <strong>storage/app/userfiles</strong> directory using a generated file name.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onUploadFiles</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$filePath</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;single_file&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">store</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;userfiles&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// ...</span>

    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;File saved&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="uploading-multiple-files"><a href="#uploading-multiple-files" class="header-anchor">#</a> Uploading Multiple Files</h3><p>When the <code>multiple</code> attribute is included with the file input, the <code>files()</code> helper will return an array instead.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Multi File<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>multi_file[]<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">multiple</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onUploadFiles</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$filePaths</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;multi_file&#39;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token variable">$file</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$filePaths</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">store</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;userfiles&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// ...</span>

    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;File saved&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="validating-file-uploads"><a href="#validating-file-uploads" class="header-anchor">#</a> Validating File Uploads</h3><p>Just like <a href="./validation.html">regular form validation</a>, files can be validated using the <code>Request</code> facade and <code>validate</code> method. Use the <code>.*</code> suffix when validating multiple items. The following checks that the uploaded file is an image and not greater than 1MB in size.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onUploadFiles</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;single_file&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|image|max:1024&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;multi_file.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|image|max:1024&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Files are valid!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="uploading-to-models"><a href="#uploading-to-models" class="header-anchor">#</a> Uploading to Models</h2><p>When working with models that are configured to use <a href="./../../extend/database/attachments.html">file attachments</a>, including Tailor models that use the <a href="./../../element/form/widget-fileupload.html">File upload widget</a>, you save file uploads directly on the model.</p><p>The simplest approach is to set the attribute on the model directly using the <code>files()</code> helper. This supports singular and multiple file uploads.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onUploadFiles</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyModel</span><span class="token punctuation">;</span>

    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;single_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// ...</span>

    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;File saved&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also set the attribute to a <code>System\\Models\\File</code> model object directly for various use cases.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromData</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Some content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;sometext.txt&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/path/to/avatar.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>See the <a href="./../../extend/database/attachments.html">file attachments article</a> to learn more about working with model-based file attachments.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/request-input.html">Requests and Input</a></li><li><a href="./../../extend/services/storage.html">Storage Disks</a></li><li><a href="./../../extend/database/attachments.html">File Attachments</a></li></ul></div>`,24))])}const q=p(u,[["render",r]]);export{v as __pageData,q as default};
